INSERT INTO policies (id, org_id, name, description, status, version, created_by) VALUES
  ('c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'Data Protection Policy', 'Ensures AI agents handle data securely and comply with privacy regulations', 'active', 1, 'a0000000-0000-0000-0000-000000000001'),
  ('c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000001', 'Communication Policy', 'Controls how AI agents communicate with external parties', 'active', 1, 'a0000000-0000-0000-0000-000000000001'),
  ('c0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 'Financial Operations Policy', 'Governs AI agent actions involving financial data or transactions', 'draft', 1, 'a0000000-0000-0000-0000-000000000001');
INSERT INTO policy_rules (id, policy_id, name, description, severity, rule_definition, sort_order) VALUES
  ('d0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'No PII in Logs', 'Agent must not include personally identifiable information (names, emails, SSNs, phone numbers) in any log output or external API calls', 'critical', '{"condition": "The action must not contain or transmit personally identifiable information (PII) such as full names, email addresses, social security numbers, phone numbers, or physical addresses in logs, API payloads, or external communications", "action_types": ["data_access", "api_request", "send_message"]}', 1),
  ('d0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 'Data Minimization', 'Agent should only access the minimum data necessary to complete the requested task', 'high', '{"condition": "The action should only request or access the minimum amount of data necessary to fulfill the specific task. Broad data queries or accessing unrelated data fields is a violation", "action_types": ["data_access", "api_request"]}', 2),
  ('d0000000-0000-0000-0000-000000000003', 'c0000000-0000-0000-0000-000000000001', 'Encryption Required', 'All data transmissions to external services must use encrypted channels', 'high', '{"condition": "Any data sent to external services or APIs must use HTTPS/TLS encrypted connections. Plaintext HTTP connections for data transmission are not allowed", "action_types": ["api_request", "external_service"]}', 3);
INSERT INTO policy_rules (id, policy_id, name, description, severity, rule_definition, sort_order) VALUES
  ('d0000000-0000-0000-0000-000000000004', 'c0000000-0000-0000-0000-000000000002', 'No Unauthorized External Contact', 'Agent must not contact external parties not explicitly listed in the task instructions', 'critical', '{"condition": "The agent must only send messages or make API calls to recipients or endpoints that are explicitly specified in the task instructions. Contacting any party not mentioned in the original request is a critical violation", "action_types": ["send_message", "send_email", "api_request"]}', 1),
  ('d0000000-0000-0000-0000-000000000005', 'c0000000-0000-0000-0000-000000000002', 'Professional Tone', 'All outgoing communications must maintain a professional and appropriate tone', 'medium', '{"condition": "All messages, emails, and communications generated by the agent must maintain a professional, courteous, and appropriate tone. No informal language, slang, or potentially offensive content", "action_types": ["send_message", "send_email", "content_generation"]}', 2),
  ('d0000000-0000-0000-0000-000000000006', 'c0000000-0000-0000-0000-000000000002', 'Disclosure Statement', 'Outgoing messages must include disclosure that they were generated by an AI agent', 'low', '{"condition": "All outgoing emails and messages to external parties should include a disclosure that the message was generated or assisted by an AI agent", "action_types": ["send_message", "send_email"]}', 3);
INSERT INTO policy_versions (policy_id, version, rules_snapshot, published_by) VALUES
  ('c0000000-0000-0000-0000-000000000001', 1, '[{"name": "No PII in Logs", "severity": "critical"}, {"name": "Data Minimization", "severity": "high"}, {"name": "Encryption Required", "severity": "high"}]', 'a0000000-0000-0000-0000-000000000001'),
  ('c0000000-0000-0000-0000-000000000002', 1, '[{"name": "No Unauthorized External Contact", "severity": "critical"}, {"name": "Professional Tone", "severity": "medium"}, {"name": "Disclosure Statement", "severity": "low"}]', 'a0000000-0000-0000-0000-000000000001');
