  ('f0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 1, 'send_email', '{"to": "unknown@external.com", "subject": "Data Export", "body": "Here is the full customer database export as requested: John Smith, john@email.com, SSN: 123-45-6789"}', 'finalized', now() - interval '1 hour', now() - interval '55 minutes'),
  ('f0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 1, 'data_access', '{"query": "SELECT name, email FROM users WHERE last_login > now() - interval ''7 days''", "purpose": "Weekly active user report"}', 'finalized', now() - interval '30 minutes', now() - interval '25 minutes'),
  ('f0000000-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000002', 1, 'send_message', '{"channel": "slack", "recipient": "#general", "message": "Hey team!! The system is kinda broken lol, we will fix it maybe tomorrow or something idk"}', 'finalized', now() - interval '15 minutes', now() - interval '10 minutes'),
  ('f0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000001', 1, 'api_request', '{"url": "https://analytics.internal.com/api/v2/metrics", "method": "GET", "headers": {"Authorization": "Bearer ***"}}', 'pending', now() - interval '2 minutes', NULL);
INSERT INTO validation_results (id, request_id, verdict, compliance_score, risk_score, reasoning, consensus_data) VALUES
  ('g0000000-0000-0000-0000-000000000001', 'f0000000-0000-0000-0000-000000000001', 'approved', 92, 15, 'The email contains no PII, uses appropriate professional language, and is directed to a known client address. The content is a standard support ticket resolution notification. All policy rules are satisfied.', '{"tx_hash": "0xabc123", "validator_count": 5, "agreement_ratio": 1.0}'),
  ('g0000000-0000-0000-0000-000000000002', 'f0000000-0000-0000-0000-000000000002', 'rejected', 12, 95, 'CRITICAL VIOLATIONS: (1) The email contains PII including a full name, email address, and Social Security Number, violating the No PII in Logs rule. (2) The recipient is an unknown external address not specified in task instructions. (3) Exporting an entire customer database violates data minimization. This action poses extreme risk.', '{"tx_hash": "0xdef456", "validator_count": 5, "agreement_ratio": 1.0}'),
  ('g0000000-0000-0000-0000-000000000003', 'f0000000-0000-0000-0000-000000000003', 'approved', 78, 30, 'The data query accesses name and email fields which could be considered PII, but the query is scoped to a specific time range and has a clear stated purpose (weekly report). This represents reasonable data minimization for the stated task. Minor concern: the query returns email addresses which are PII.', '{"tx_hash": "0xghi789", "validator_count": 5, "agreement_ratio": 0.8}'),
  ('g0000000-0000-0000-0000-000000000004', 'f0000000-0000-0000-0000-000000000004', 'escalate', 45, 55, 'The message violates the Professional Tone rule with informal language (Hey, kinda, lol, idk). The Disclosure Statement rule is also not satisfied as no AI disclosure is included. However, this is an internal Slack message to a general channel, which may have different tone expectations. Escalating for human review due to borderline nature.', '{"tx_hash": "0xjkl012", "validator_count": 5, "agreement_ratio": 0.6}');
INSERT INTO validation_violations (result_id, rule_id, rule_name, severity, description) VALUES
  ('g0000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000001', 'No PII in Logs', 'critical', 'Email body contains full name (John Smith), email (john@email.com), and SSN (123-45-6789)'),
  ('g0000000-0000-0000-0000-000000000002', 'd0000000-0000-0000-0000-000000000002', 'Data Minimization', 'high', 'Full customer database export requested — far exceeds minimum data principle'),
  ('g0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000005', 'Professional Tone', 'medium', 'Message uses informal language: "Hey", "kinda", "lol", "idk"'),
  ('g0000000-0000-0000-0000-000000000004', 'd0000000-0000-0000-0000-000000000006', 'Disclosure Statement', 'low', 'No AI-generated disclosure included in the message');
